layout(binding = 2) buffer HAct { float16_t hact[]; };
#define TILE 16
#ifndef HEAD_DIM
#define HEAD_DIM 128
#endif
#define HDT (HEAD_DIM / TILE)
#ifndef SRC_HEAD_DIM
#define SRC_HEAD_DIM HEAD_DIM
#endif
#ifndef BIAS
#define BIAS 0
#endif
#if BIAS
#define QBIAS(head, d) + wbuf[pc.wOff + (head) * HEAD_DIM + (d)]
#else
#define QBIAS(head, d)
#endif
#define WG 256
#ifndef TPW
#define TPW 1
#endif
layout(local_size_x = WG) in;
shared float rows[TILE * HEAD_DIM];
void main() {
    uint head = gl_WorkGroupID.y;
    uint tid = gl_LocalInvocationID.x;
    uint plane = pc.outOff + (head * (pc.aux1 / TILE)) * (HDT * TILE * TILE);
    for (uint s = 0u; s < uint(TPW); ++s) {
        uint tt = gl_WorkGroupID.x * uint(TPW) + s; // token tile
        if (pc.aux2 != 0u && tt >= pc.aux2) {
            return;
        }
        uint tok0 = tt * TILE;
        if (s > 0u) {
            barrier();
        }
        for (uint i = tid; i < TILE * HEAD_DIM; i += WG) {
            uint m = i / HEAD_DIM, d = i % HEAD_DIM;
            uint token = tok0 + m;
#if SRC_HEAD_DIM != HEAD_DIM
            rows[i] = (token < pc.tokens && d < SRC_HEAD_DIM)
                ? act[pc.inOff + token * pc.dim + head * SRC_HEAD_DIM + d] * uintBitsToFloat(pc.scale)
                : 0.0;
#else
            rows[i] = (token < pc.tokens)
                ? (act[pc.inOff + token * pc.dim + head * HEAD_DIM + d] QBIAS(head, d))
                    * uintBitsToFloat(pc.scale)
                : 0.0;
#endif
        }
        barrier();
        uint base = plane + tt * (HDT * TILE * TILE);
        for (uint o = tid; o < HDT * TILE * TILE; o += WG) {
            uint c = o / (TILE * TILE);      // component tile
            uint rem = o % (TILE * TILE);
            uint m, d;
            if (pc.aux0 == 0u) {
                m = rem / TILE;             // (token, component)
                d = c * TILE + rem % TILE;
            } else {
                m = rem % TILE;             // transposed: (component, token)
                d = c * TILE + rem / TILE;
            }
            hact[base + o] = float16_t(rows[m * HEAD_DIM + d]);
        }
    }
}
#version 450
#include "dit_common.glsl"
layout(local_size_x = 256) in;
void main() {
    uint idx = gl_GlobalInvocationID.x;
    uint halfDim = pc.headDim / 2u;
    uint total = pc.tokens * pc.heads * halfDim;
    if (idx >= total) {
        return;
    }
    uint j = idx % halfDim;
    uint h = (idx / halfDim) % pc.heads;
    uint token = idx / (halfDim * pc.heads);
    float c = wbuf[pc.wOff + token * halfDim + j];
    float s = wbuf[pc.aux0 + token * halfDim + j];
    uint base = pc.inOff + token * pc.dim + h * pc.headDim + j;
    float lo = act[base];
    float hi = act[base + halfDim];
    act[base] = lo * c - hi * s;
    act[base + halfDim] = hi * c + lo * s;
}

