	b.mu.Lock()
	err := fmt.Errorf("backend: the embedding model is closed")
	if b.gpu != nil {
		err = b.opt.Device.Do(func(*vk.Device) error {
			var e error
			vecs, e = b.gpu.EmbedBatch(seqs)
			return e
		})
	}
	b.mu.Unlock()

	b.qmu.Lock()
	defer b.qmu.Unlock()
	b.passes++
	for n, t := range take {
		j := jobs[t.job]
		if j.left < 0 {
			continue
		}
		if err != nil {
			j.finish(err)
			continue
		}
		j.vecs[t.i] = vecs[n]
		if j.left--; j.left == 0 {
			j.finish(nil)
		}
	}
	b.dropFinished()
	return true
}

